-- Integration checks use isolated fixtures and always roll back.
begin;
set local statement_timeout='45s';
create function pg_temp.fail_fixture_note() returns trigger language plpgsql as $$
begin if current_setting('relay.test_fail',true)='on' and old.id::text=current_setting('relay.test_note',true) then raise exception 'fixture failure';end if;return new;end $$;
create trigger zz_fixture_failure before update on public.notes for each row execute function pg_temp.fail_fixture_note();
create temporary table fixture_results(check_name text primary key);
grant select, insert on fixture_results to authenticated;
do $$
declare u uuid; outsider uuid:=gen_random_uuid(); w uuid; obj uuid; src uuid; dst uuid; other uuid; alias_id uuid; task_id uuid; note_id uuid; list_id uuid; source_entry uuid; target_entry uuid; source_link uuid; target_link uuid; portal_id uuid; item_id uuid; h uuid; m jsonb; sv integer;tv integer;expected_audit bigint; preview jsonb;
begin
 select id into u from auth.users order by created_at limit 1;
 if u is null then raise exception 'Create at least one authenticated account before running these tests';end if;
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 w:=public.create_workspace('Fixture fusion — rollback');
 select id into obj from public.objects where workspace_id=w and slug='people';
 insert into public.records(workspace_id,object_id,display_name,email,attributes) values(w,obj,'Source fixture','fixture@example.invalid','{"source_only":"source"}') returning id into src;
 insert into public.records(workspace_id,object_id,display_name,email,attributes) values(w,obj,'Target fixture','fixture@example.invalid','{"target_only":"target"}') returning id into dst;
 insert into public.records(workspace_id,object_id,display_name) values(w,obj,'Related fixture') returning id into other;
 insert into public.records(workspace_id,object_id,display_name,archived,merged_into) values(w,obj,'Earlier alias',true,src) returning id into alias_id;
 insert into public.tasks(workspace_id,record_id,title) values(w,src,'Fixture task') returning id into task_id;
 insert into public.notes(workspace_id,record_id,content,private,author_id) values(w,src,'private fixture content',true,u) returning id into note_id;
 insert into public.lists(workspace_id,object_id,name,visibility,creator_id) values(w,obj,'Private fixture list','private',u) returning id into list_id;
 insert into public.list_entries(workspace_id,list_id,record_id,attributes) values(w,list_id,src,'{"budget":"source"}') returning id into source_entry;
 insert into public.list_entries(workspace_id,list_id,record_id,attributes) values(w,list_id,dst,'{"budget":"target"}') returning id into target_entry;
 insert into public.record_relations(workspace_id,source_id,target_id,label) values(w,src,other,'Partner') returning id into source_link;
 insert into public.record_relations(workspace_id,source_id,target_id,label) values(w,dst,other,'Partner') returning id into target_link;
 insert into public.portals(workspace_id,record_id,name) values(w,src,'Fixture portal') returning id into portal_id;
 insert into public.portal_items(workspace_id,portal_id,title) values(w,portal_id,'Fixture shared item') returning id into item_id;
 select count(*) into expected_audit from public.audit_events where workspace_id=w;
 perform set_config('relay.test_note',note_id::text,true);perform set_config('relay.test_fail','on',true);
 begin
  perform public.merge_records(w,src,dst,1,1,'{"display_name":"source"}');
  raise exception 'Expected mid-transaction failure';
 exception when raise_exception then if sqlerrm<>'fixture failure' then raise;end if;end;
 if (select count(*) from public.merge_history where workspace_id=w)<>0 or (select version from public.records where id=dst)<>1 or (select record_id from public.tasks where id=task_id)<>src or (select count(*) from public.audit_events where workspace_id=w)<>expected_audit then raise exception 'Partial merge survived rollback';end if;
 insert into fixture_results values('atomic rollback including audit, fields and children');
 perform set_config('relay.test_fail','off',true);
 begin perform public.merge_records(w,src,dst,0,1,'{}');raise exception 'Expected invalid version rejection';exception when sqlstate '22023' then null;end;
 update public.records set display_name='Edited target' where id=dst;
 begin perform public.merge_records(w,src,dst,1,1,'{}');raise exception 'Expected stale version rejection';exception when sqlstate '40001' then null;end;
 insert into fixture_results values('server version check after comparison edit');
 execute 'set local role authenticated';
 m:=public.merge_records(w,src,dst,1,2,'{"display_name":"source"}');h:=(m->>'merge_id')::uuid;
 if h is null or not(select restorable from public.merge_history where id=h) or (select merged_into from public.records where id=src)<>dst or (select record_id from public.tasks where id=task_id)<>dst or (select record_id from public.notes where id=note_id)<>dst or (select merged_into from public.records where id=alias_id)<>dst then raise exception 'Merge did not preserve and move context';end if;

 insert into fixture_results values('successful merge with private context and alias flattening');
 if (select count(*) from public.audit_events where workspace_id=w and entity='merge_history')<2 or (select snapshot::text from public.merge_history where id=h) like '%private fixture content%' then raise exception 'Audit missing or private content exposed';end if;
 insert into fixture_results values('durable public audit without private note content');
 select version into sv from public.records where id=src;select version into tv from public.records where id=dst;
 preview:=public.preview_undo_merge(w,h);if not (preview->>'available')::boolean then raise exception 'Fresh merge should be restorable';end if;
 perform public.undo_merge(w,h,sv,tv);
 if (select archived from public.records where id=src) or (select merged_into from public.records where id=src) is not null or (select display_name from public.records where id=dst)<>'Edited target' or (select record_id from public.tasks where id=task_id)<>src or (select record_id from public.notes where id=note_id)<>src or (select private from public.notes where id=note_id) is not true or (select author_id from public.notes where id=note_id)<>u or (select content from public.notes where id=note_id)<>'private fixture content' or (select merged_into from public.records where id=alias_id)<>src then raise exception 'Undo did not restore fields and private context';end if;
 if not exists(select 1 from public.list_entries where id=source_entry and record_id=src and attributes='{"budget":"source"}') or not exists(select 1 from public.list_entries where id=target_entry and record_id=dst and attributes='{"budget":"target"}' and merge_provenance='[]') or not exists(select 1 from public.record_relations where id=source_link and source_id=src) or not exists(select 1 from public.record_relations where id=target_link and source_id=dst) or (select record_id from public.portals where id=portal_id)<>src or not exists(select 1 from public.portal_items where id=item_id) then raise exception 'Undo did not restore lists, links and portal';end if;
 if (select undone_at from public.merge_history where id=h) is null or (select undone_by from public.merge_history where id=h)<>u or (select version from public.records where id=dst)<=tv then raise exception 'Undo audit or increasing versions missing';end if;
 insert into fixture_results values('undo restores fields, list collisions, relation ids, aliases and portal');
 m:=public.undo_merge(w,h,sv,tv);if not (m->>'already_undone')::boolean then raise exception 'Undo replay should be idempotent';end if;
 insert into fixture_results values('undo replay is idempotent');
 select version into sv from public.records where id=src;select version into tv from public.records where id=dst;
 perform public.decide_duplicate(w,src,dst,sv,tv,'separate');
 begin perform public.merge_records(w,src,dst,sv,tv,'{}');raise exception 'Expected separated pair rejection';exception when sqlstate '22023' then null;end;
 if (select count(*) from public.duplicate_decisions where workspace_id=w and status='separate')<>1 then raise exception 'Separate decision missing';end if;
 perform public.decide_duplicate(w,src,dst,null,null,'reopen');
 perform public.decide_duplicate(w,src,dst,sv,tv,'deferred');
 if not exists(select 1 from public.duplicate_decisions where workspace_id=w and defer_until=now()+interval '7 days') then raise exception 'Deferred decision missing';end if;
 begin perform public.decide_duplicate(w,src,dst,sv-1,tv,'separate');raise exception 'Expected stale decision rejection';exception when sqlstate '40001' then null;end;
 perform public.decide_duplicate(w,src,dst,null,null,'reopen');
 insert into fixture_results values('separate, defer, reopen and stale decision checks');
 execute 'reset role';
 update public.memberships set role='viewer' where workspace_id=w and user_id=u;
 begin perform public.merge_records(w,src,dst,sv,tv,'{}');raise exception 'Expected viewer rejection';exception when insufficient_privilege then null;end;
 begin perform public.decide_duplicate(w,src,dst,sv,tv,'separate');raise exception 'Expected viewer decision rejection';exception when insufficient_privilege then null;end;
 begin perform public.undo_merge(w,h,sv,tv);raise exception 'Expected viewer undo rejection';exception when insufficient_privilege then null;end;
 update public.memberships set role='owner' where workspace_id=w and user_id=u;
 insert into fixture_results values('viewer cannot merge, decide or undo');
 m:=public.merge_records(w,src,dst,sv,tv,'{}');h:=(m->>'merge_id')::uuid;
 select version into sv from public.records where id=src;select version into tv from public.records where id=dst;
 update public.notes set content='edited after merge' where id=note_id;
 begin perform public.undo_merge(w,h,sv,tv);raise exception 'Expected post-merge change rejection';exception when sqlstate '40001' then null;end;
 if (select content from public.notes where id=note_id)<>'edited after merge' or (select archived from public.records where id=src) is not true or (select undone_at from public.merge_history where id=h) is not null then raise exception 'Unsafe undo overwrote later edits';end if;
 insert into fixture_results values('undo refuses later edits without changing data');
 execute 'set local role authenticated';
 begin perform count(*) from relay_private.merge_restore_points;raise exception 'Expected private snapshot access rejection';exception when insufficient_privilege then null;end;
 begin perform relay_private.merge_records_v1(w,src,dst,sv,tv,'{}');raise exception 'Expected legacy RPC bypass rejection';exception when insufficient_privilege then null;end;
 execute 'reset role';
 insert into fixture_results values('private restore points and legacy bypass are inaccessible');
end $$;
select check_name,'PASS' as result from fixture_results order by check_name;
rollback;
